    /// <summary>
    /// Modified field logic
    /// </summary>
    /// <param name="_fieldId">
    /// The instance of <c>FieldId</c> class.
    /// </param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METCBCTInvoiceLine, ItemId):
            case fieldNum(METCBCTInvoiceLine, InventSiteId):
                this.assignFinancialDimension();
                break;
        }
    }

    /// <summary>
    /// Set financial dimension on the line.
    /// Copied from the Charge through header and updated with the default Department dimensions from the Service Item.
    /// If the service item on the customer line does not have a default department code, the department code of the vendor line will be used on the customer line.
    /// </summary>
    private void assignFinancialDimension()
    {
        InventTable                         inventTable = InventTable::find(this.ItemId);
        DimensionAttributeRecId             departmentDimensionAttributeRecId = DimensionAttribute::findByName('Department').RecId;

        // CB411_412_ChargeThrough fin dim copied from the Charge through header
        this.FinancialDimension = this.CBCTInvoiceHeaderTable().FinancialDimension;

        // Get the department from the service item
        if (METCBCTInvoiceLine::checkItemHasDepartmentDimension(inventTable.ItemId))
        {
            this.setFinancialDimension(inventTable.DefaultDimension, departmentDimensionAttributeRecId);
        }

        // Get the Cost centre from Charge Through Site – Off Remit – Cost Centre Link
        METCBCTCustomerSiteOffRemitCostCentreLink     customerSiteOffRemitCostCentreLink;
        InventSiteId                                    inventSiteId = this.InventSiteId;

        select firstonly customerSiteOffRemitCostCentreLink where customerSiteOffRemitCostCentreLink.InventSiteId == inventSiteId;
        if (customerSiteOffRemitCostCentreLink.RecId)
        {
            this.setCostCentre(this.FinancialDimension,'CostCentre', customerSiteOffRemitCostCentreLink.CostCentre);
        }

        //else if (this.CustVend == CustVendACType::Cust)
        // CB411_412_ChargeThrough same item is used for both vendor/customer lines so they will have the same department dimension
        /*else if (this.VendCustType == METCBCTVendCust::Cust)
        {
            //If the current line is of type customer then default department from the item of line type vendor for the charge through invoice 
            METCBCTInvoiceLine      invoiceLineVendor;

            select firstonly ItemId 
                from invoiceLineVendor
                where invoiceLineVendor.HeaderNumber == this.HeaderNumber 
                && invoiceLineVendor.VendCustType == METCBCTVendCust::Vend;

            if (invoiceLineVendor.ItemId && METCBCTInvoiceLine::checkItemHasDepartmentDimension(invoiceLineVendor.ItemId))
            {
                this.setFinancialDimension(InventTable::find(invoiceLineVendor.ItemId).DefaultDimension, departmentDimensionAttributeRecId);
            }
        }*/
    }

