    /// <summary>
    /// Set financial dimension
    /// </summary>
    /// <param name="_itemDefaultDimension">
    /// The instance of <c>DimensionDefault</c> class.
    /// </param>
    /// <param name="_departmentDimensionAttributeRecId">
    /// The instance of <c>DimensionAttributeRecId</c> class.
    /// </param>
    public void setFinancialDimension(DimensionDefault  _itemDefaultDimension, DimensionAttributeRecId  _departmentDimensionAttributeRecId)
    {
        this.FinancialDimension = DimensionDefaultFacade::serviceReplaceAttributeValue(this.FinancialDimension,_itemDefaultDimension,_departmentDimensionAttributeRecId);
    }

    /// <summary>
    ///  Check if the item has department dimension defined.
    /// </summary>
    /// <param name="_itemId">
    /// The instance of <c>ItemId</c> class.
    /// </param>
    /// <returns>
    /// True if item has department dimension.
    /// </returns>
    public Static boolean checkItemHasDepartmentDimension(ItemId   _itemId)
    {
        boolean                             ret;
        InventTable                         inventTable = InventTable::find(_itemId);
        DimensionAttributeValueSetStorage   dimStorage;
        DimensionValue                      departmentDimensionValue;
        DimensionAttributeRecId             departmentDimensionAttributeRecId = DimensionAttribute::findByName('Department').RecId;

        dimStorage = DimensionAttributeValueSetStorage::find(inventTable.DefaultDimension);
        departmentDimensionValue = dimStorage.getDisplayValueByDimensionAttribute(departmentDimensionAttributeRecId);

        ret = departmentDimensionValue ? true : false;

        return ret;
    }

/// <summary>
/// Init value for the table fields 
/// </summary>
public void initValue()
{
    this.Qty = 1;
    super();
}

    /// <summary>
    ///  Find the related record of METCBCTInvoiceHeaderTable.
    /// </summary>
    /// <returns>
    /// returns instance of METCBCTInvoiceHeaderTable.
    /// </returns>
    public METCBCTInvoiceHeaderTable    ctInvoiceHeaderTable()
    {
        METCBCTInvoiceHeaderTable       cTInvoiceHeaderTable;

        select cTInvoiceHeaderTable 
            where cTInvoiceHeaderTable.Number == this.HeaderNumber;

        return cTInvoiceHeaderTable;
    }

    /// <summary>
    ///  Returns the METVendTable record linked to the current buffer.
    /// </summary>
    /// <returns>
    ///  Returns instance of METVendTable.
    /// </returns>
    public METVendTable     MetVendTable()
    {
        METVendTable                metVendTable;
        METCBCTInvoiceHeaderTable   cTInvoiceHeaderTable = this.ctInvoiceHeaderTable();

        select metVendTable 
            where metVendTable.AccountNum == cTInvoiceHeaderTable.VendorAccount;

        return metVendTable;
    }

/// <summary>
/// Find the related InventTable record
/// </summary>
/// <returns>
/// Returns instance of InventTable.
/// </returns>
public InventTable inventTable()
{
    return InventTable::find(this.ItemId);
}

/// <summary>
/// Exist method
/// </summary>
/// <param name = "_headerNumber">CT number</param>
/// <returns>True if it exists; otherwise, false.</returns>
static boolean exist(METCBCTNumber _headerNumber)
{
    return _headerNumber && (select firstonly RecId from METCBCTInvoiceLine
                                where METCBCTInvoiceLine.HeaderNumber == _headerNumber).RecId != 0;
}

/// <summary>
/// CB411_412_ChargeThrough
/// </summary>
/// <param name = "_forupdate">select <c>METCBCTInvoiceHeaderTable</c> for update</param>
/// <returns><c>METCBCTInvoiceHeaderTable</c> record</returns>
METCBCTInvoiceHeaderTable CBCTInvoiceHeaderTable(boolean _forupdate = false)
{
    return METCBCTInvoiceHeaderTable::find(this.HeaderNumber, _forupdate);
}

    /// <summary>
    /// Set profit centre
    /// </summary>
    /// <param name = "_defaultDimension">
    /// Dimension default value
    /// </param>
    ///  <param name = "_dimensionName">
    /// Dimension name
    /// </param>
    ///  <param name = "_dimensionValue">
    /// Dimension value
    /// </param>
    public void setCostCentre(DimensionDefault _defaultDimension,
                                Name             _dimensionName,
                                DimensionValue   _dimensionValue)
    {
        //'ProfitCentre'
        DimensionAttribute                  dimAttribute;
        DimensionAttributeValue             dimAttributeValue;
        DimensionAttributeValueSetStorage   dimStorage;

        dimStorage      = DimensionAttributeValueSetStorage::find(_defaultDimension);
        dimAttribute    = DimensionAttribute::findByName(_dimensionName);

        if (_dimensionValue)
        {
            dimAttributeValue = DimensionAttributeValue::findByDimensionAttributeAndValue(dimAttribute, _dimensionValue, true, true);
            dimStorage.addItem(dimAttributeValue);
        }
        else
        {
            dimStorage.removeDimensionAttribute(dimAttribute.RecId);
        }

        this.FinancialDimension = dimStorage.save();
    }
